import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "rain-window.html"
MODEL_ID = "storm-model"

DRIVER = r"""
import { step } from './model.mjs';

const R = (v) => Math.round(v * 1000) / 1000;
const s0 = step(0);

let finite = true;
let minLen = Infinity, minVy = Infinity;
let vxMin = Infinity, vxMax = -Infinity;
let dropMinX = Infinity, dropMaxX = -Infinity;
let dropMinY = Infinity, dropMaxY = -Infinity;
const layers = new Map();
for (const t of [0, 3.7, 11.2]) {
  for (const d of step(t).drops) {
    for (const k of ['x', 'y', 'len', 'vx', 'vy']) {
      if (typeof d[k] !== 'number' || !Number.isFinite(d[k])) finite = false;
    }
    if (!Number.isInteger(d.layer)) finite = false;
    minLen = Math.min(minLen, d.len);
    minVy = Math.min(minVy, d.vy);
    vxMin = Math.min(vxMin, d.vx);
    vxMax = Math.max(vxMax, d.vx);
    dropMinX = Math.min(dropMinX, d.x); dropMaxX = Math.max(dropMaxX, d.x);
    dropMinY = Math.min(dropMinY, d.y); dropMaxY = Math.max(dropMaxY, d.y);
    const row = layers.get(d.layer) || { n: 0, vy: 0, vx: 0 };
    row.n += 1; row.vy += d.vy; row.vx += Math.abs(d.vx);
    layers.set(d.layer, row);
  }
}
const layerRows = [...layers.entries()]
  .map(([layer, v]) => ({ layer, n: v.n, vy: R(v.vy / v.n), vx: R(v.vx / v.n) }))
  .sort((a, b) => a.layer - b.layer);

const runners = [], splash = [];
for (let i = 0; i <= 96; i++) {
  const s = step(i * 0.25);
  runners.push(s.runners.map((r) => [r.id, R(r.x), R(r.y), R(r.r)]));
  let lo = Infinity, hi = -Infinity;
  for (const sp of s.splashes) { lo = Math.min(lo, sp.y); hi = Math.max(hi, sp.y); }
  splash.push([s.splashes.length, s.splashes.length ? R(lo) : 0, s.splashes.length ? R(hi) : 0]);
}

const flash = [];
for (let i = 0; i <= 1200; i++) flash.push(Math.round(step(i * 0.05).flash * 10000) / 10000);

console.log(JSON.stringify({
  width: s0.width, height: s0.height, puddleY: s0.puddleY,
  n: s0.drops.length, finite, minLen: R(minLen), minVy: R(minVy),
  vxMin: R(vxMin), vxMax: R(vxMax),
  dropMinX: R(dropMinX), dropMaxX: R(dropMaxX),
  dropMinY: R(dropMinY), dropMaxY: R(dropMaxY),
  layers: layerRows, runners, splash, flash, dt: 0.05
}));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def group_strikes(flash, dt, level=0.6, gap=1.0):
    """Indices of samples above `level`, clustered into one group per strike.

    A strike may flicker (several peaks inside a fifth of a second); anything
    closer together than `gap` seconds is the same strike.
    """
    groups, cur = [], None
    for i, v in enumerate(flash):
        if v < level:
            continue
        if cur is not None and (i - cur[-1]) * dt <= gap:
            cur.append(i)
        else:
            if cur:
                groups.append(cur)
            cur = [i]
    if cur:
        groups.append(cur)
    return groups


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.model = cls.extract_model(cls.raw)
        cls.data = cls.run_model(cls.model) if cls.model and node() else None

    @staticmethod
    def extract_model(raw):
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % MODEL_ID,
                      raw, re.S | re.I)
        return m.group(1) if m else None

    @staticmethod
    def run_model(src):
        with tempfile.TemporaryDirectory() as tmp:
            d = Path(tmp)
            (d / "model.mjs").write_text(src, encoding="utf-8")
            (d / "driver.mjs").write_text(DRIVER, encoding="utf-8")
            done = subprocess.run([node(), str(d / "driver.mjs")], capture_output=True,
                                  text=True, timeout=120, cwd=d)
            if done.returncode != 0:
                raise AssertionError("model failed in node: %s" % done.stderr[-800:])
            return json.loads(done.stdout.strip().splitlines()[-1])

    def model_data(self):
        if node() is None:
            raise unittest.SkipTest("node is required to measure the model")
        self.assertIsNotNone(self.model,
                             'no <script id="%s"> block found' % MODEL_ID)
        self.assertIsNotNone(self.data, "model produced no data")
        return self.data

    def runner_frames(self):
        return [{int(r[0]): (r[1], r[2], r[3]) for r in frame}
                for frame in self.model_data()["runners"]]

    # --- the page itself -------------------------------------------------
    def test_is_one_self_contained_html_page(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        self.assertIn("<canvas", self.raw.lower())

    def test_no_external_requests(self):
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I),
                              "page must be self-contained: found %s" % why)

    def test_animates_with_request_animation_frame(self):
        self.assertIn("requestAnimationFrame", self.raw)

    def test_model_is_separate_from_the_renderer(self):
        self.assertIsNotNone(self.model,
                             'the pure model must live in <script id="%s">' % MODEL_ID)
        for banned in ("getContext", "document.", "window.", "canvas"):
            self.assertNotIn(banned, self.model,
                             "model script must be pure math, found %r" % banned)

    # --- the rain, measured ----------------------------------------------
    def test_rain_falls_in_depth_layers(self):
        data = self.model_data()
        self.assertGreaterEqual(data["n"], 200, "a storm needs >=200 drops, got %s" % data["n"])
        self.assertLessEqual(data["n"], 20000, "drop count is implausible")
        self.assertTrue(data["finite"], "every drop needs finite x, y, len, vx, vy and an int layer")
        self.assertGreater(data["minLen"], 0, "every streak must have a positive length")
        self.assertGreater(data["minVy"], 0, "rain must fall: vy must be positive")
        rows = data["layers"]
        self.assertGreaterEqual(len(rows), 3, "need >=3 depth layers, got %s" % len(rows))
        total = sum(r["n"] for r in rows)
        for r in rows:
            self.assertGreaterEqual(r["n"], 0.05 * total,
                                    "layer %s holds only %s of %s drops"
                                    % (r["layer"], r["n"], total))

    def test_near_layers_fall_faster_than_far_ones(self):
        rows = self.model_data()["layers"]
        speeds = [r["vy"] for r in rows]
        for a, b in zip(speeds, speeds[1:]):
            self.assertGreater(b, a, "layer speeds must rise with depth index: %s" % speeds)
        self.assertGreaterEqual(speeds[-1], 1.3 * speeds[0],
                                "nearest layer must fall >=1.3x the farthest: %.1f vs %.1f"
                                % (speeds[-1], speeds[0]))

    def test_rain_is_wind_driven(self):
        data = self.model_data()
        self.assertGreater(data["vxMin"] * data["vxMax"], 0,
                           "wind blows one way: vx ranges %s..%s" % (data["vxMin"], data["vxMax"]))
        near = data["layers"][-1]
        self.assertGreaterEqual(near["vx"], 0.1 * near["vy"],
                                "rain falls straight down: |vx| %.1f vs vy %.1f"
                                % (near["vx"], near["vy"]))

    def test_rain_stays_in_the_pane_and_above_the_puddle(self):
        data = self.model_data()
        w, h, puddle = data["width"], data["height"], data["puddleY"]
        self.assertGreater(puddle, 0.5 * h, "the puddle line sits low in the pane")
        self.assertLess(puddle, 0.97 * h, "the puddle line needs room below it")
        self.assertLessEqual(data["dropMaxY"], puddle + 2,
                             "drops fall past the puddle line: %s > %s"
                             % (data["dropMaxY"], puddle))
        self.assertGreaterEqual(data["dropMinY"], -0.5 * h, "drops start absurdly high")
        self.assertGreaterEqual(data["dropMinX"], -0.5 * w, "drops blow out of frame")
        self.assertLessEqual(data["dropMaxX"], 1.5 * w, "drops blow out of frame")

    # --- the droplets on the glass ---------------------------------------
    def test_droplets_live_on_the_glass(self):
        data = self.model_data()
        w, puddle = data["width"], data["puddleY"]
        for i, frame in enumerate(data["runners"]):
            self.assertGreaterEqual(len(frame), 3, "frame %d has no droplets" % i)
            self.assertLessEqual(len(frame), 400, "frame %d has %d droplets" % (i, len(frame)))
            for rid, x, y, r in frame:
                self.assertEqual(int(rid), rid, "droplet id must be an integer")
                self.assertGreater(r, 0, "droplet radius must be positive")
                self.assertTrue(0 <= x <= w, "droplet x %s outside the pane" % x)
                self.assertTrue(0 <= y <= puddle + 1, "droplet y %s off the glass" % y)

    def test_droplets_only_ever_run_downwards(self):
        frames = self.runner_frames()
        for i, (a, b) in enumerate(zip(frames, frames[1:])):
            for rid, (_, y, _) in a.items():
                if rid in b:
                    self.assertGreaterEqual(b[rid][1], y - 1e-6,
                                            "droplet %s ran UP between frame %d and %d: %s -> %s"
                                            % (rid, i, i + 1, y, b[rid][1]))
        seen = {}
        for frame in frames:
            for rid, (_, y, _) in frame.items():
                lo, hi = seen.get(rid, (y, y))
                seen[rid] = (min(lo, y), max(hi, y))
        runs = sum(1 for lo, hi in seen.values() if hi - lo > 15)
        self.assertGreaterEqual(runs, 5,
                                "droplets must actually run down the glass; only %d moved" % runs)

    def test_droplets_merge_and_never_shrink(self):
        frames = self.runner_frames()
        growth = 0
        for i, (a, b) in enumerate(zip(frames, frames[1:])):
            for rid, (_, _, r) in a.items():
                if rid not in b:
                    continue
                self.assertGreaterEqual(b[rid][2], r - 1e-6,
                                        "droplet %s shrank between frame %d and %d: %s -> %s"
                                        % (rid, i, i + 1, r, b[rid][2]))
                if b[rid][2] > r + 1e-6:
                    growth += 1
        self.assertGreaterEqual(growth, 3,
                                "droplets never merge: only %d radius gains in 24s" % growth)

    # --- the puddle -------------------------------------------------------
    def test_splashes_land_on_the_puddle_line(self):
        data = self.model_data()
        puddle = data["puddleY"]
        counts = [row[0] for row in data["splash"]]
        self.assertGreaterEqual(max(counts), 3,
                                "the puddle never splashes: peak count %d" % max(counts))
        self.assertGreater(len(set(counts)), 1, "splash count never changes")
        for n, lo, hi in data["splash"]:
            if not n:
                continue
            self.assertGreaterEqual(lo, puddle - 60, "a splash flew %s above the puddle" % lo)
            self.assertLessEqual(hi, puddle + 8, "a splash sank %s below the puddle" % hi)

    # --- the lightning ----------------------------------------------------
    def test_lightning_strikes_on_a_regular_schedule(self):
        data = self.model_data()
        flash, dt = data["flash"], data["dt"]
        self.assertTrue(all(0 <= v <= 1 for v in flash), "flash must stay within 0..1")
        self.assertLess(min(flash), 0.05, "the scene is never dark between strikes")
        groups = group_strikes(flash, dt)
        self.assertGreaterEqual(len(groups), 3,
                                "need >=3 strikes in %.0fs, found %d"
                                % (len(flash) * dt, len(groups)))
        onsets = [g[0] * dt for g in groups]
        gaps = [b - a for a, b in zip(onsets, onsets[1:])]
        mean = sum(gaps) / len(gaps)
        self.assertGreater(mean, 0, "strikes must be spread out in time")
        for g in gaps:
            self.assertLess(abs(g - mean), 0.1 * mean,
                            "strikes are not on a schedule: gaps %s" % gaps)

    def test_lightning_flash_decays(self):
        data = self.model_data()
        flash, dt = data["flash"], data["dt"]
        groups = group_strikes(flash, dt)
        checked = 0
        for g in groups:
            peak_i = max(g, key=lambda i: flash[i])
            peak = flash[peak_i]
            self.assertGreater(peak, 0.6, "a strike must actually light the scene")
            late, gone = peak_i + int(round(1.5 / dt)), peak_i + int(round(2.5 / dt))
            if gone >= len(flash):
                continue
            checked += 1
            self.assertLessEqual(flash[late], 0.25 * peak,
                                 "flash at +1.5s is %.3f, peak was %.3f" % (flash[late], peak))
            self.assertLess(flash[gone], 0.1,
                            "flash at +2.5s is %.3f, it should be gone" % flash[gone])
        self.assertGreaterEqual(checked, 2, "not enough strikes to measure the decay")


if __name__ == "__main__":
    unittest.main()
